alter table public.profiles add column if not exists profile_theme text not null default 'cinematic'; alter table public.profiles drop constraint if exists profiles_profile_theme_check; alter table public.profiles add constraint profiles_profile_theme_check check (profile_theme = any (array['cinematic','minimal','neon','classic']::text[])); drop view if exists public.public_artist_releases; drop view if exists public.public_artist_profiles;
